 <div class="bh-main-grid"><section class="bh-card bh-chart-card"><div class="bh-card__heading"><div><h2>روند فروش و سفارش‌ها</h2><p>محاسبه‌شده از سفارش‌های واقعی ووکامرس</p></div><span class="bh-source-badge">منبع: ووکامرس</span></div><?php if ( empty( $data['chart'] ) ) : ?><div class="bh-empty" role="status"><span class="dashicons dashicons-chart-area" aria-hidden="true"></span><strong>داده‌ای برای نمایش وجود ندارد</strong><span>پس از ثبت سفارش، روند فروش اینجا نمایش داده می‌شود.</span></div><?php else : ?><div class="bh-chart" role="img" aria-label="نمودار فروش و تعداد سفارش‌ها"><?php $max_sales = max( 1, max( array_map( function ( $point ) { return (float) $point['sales']; }, $data['chart'] ) ) ); foreach ( $data['chart'] as $point ) : ?><div class="bh-chart__item"><div class="bh-chart__bar" style="height:<?php echo esc_attr( max( 8, (int) ( ( (float) $point['sales'] / $max_sales ) * 180 ) ) ); ?>px" title="<?php echo esc_attr( wp_strip_all_tags( wc_price( $point['sales'] ) ) . '، ' . $point['orders'] . ' سفارش' ); ?>"></div><small><?php echo esc_html( Baharan_Home_Dashboard_Data::format_date( strtotime( $point['date'] ), true ) ); ?></small><b><?php echo esc_html( $point['orders'] ); ?></b></div><?php endforeach; ?></div><?php endif; ?></section>
