 <div class="bh-secondary-grid"><section class="bh-card"><div class="bh-card__heading"><div><h2>نیازمند رسیدگی</h2><p><?php echo esc_html( $data['kpis']['attention'] ); ?> سفارش در انتظار اقدام</p></div></div><?php if ( empty( $data['attention_orders'] ) ) : ?><div class="bh-empty bh-empty--compact"><span class="dashicons dashicons-yes-alt" aria-hidden="true"></span><span>سفارش معوق یا ناموفق وجود ندارد.</span></div><?php else : ?><div class="bh-list"><?php foreach ( $data['attention_orders'] as $order ) : ?><a href="<?php echo esc_url( $order['url'] ); ?>" class="bh-list__row"><span>#<?php echo esc_html( $order['number'] ); ?><small><?php echo esc_html( $order['status'] ); ?></small></span><strong><?php echo wp_kses_post( $order['total'] ); ?></strong></a><?php endforeach; ?></div><?php endif; ?></section>
 <section class="bh-card"><div class="bh-card__heading"><div><h2>موجودی و پرفروش‌ها</h2><p>بر اساس محصولات منتشرشده و سفارش‌های واقعی</p></div></div><div class="bh-split-list"><div><h3>موجودی کم</h3><?php if ( empty( $data['low_stock_items'] ) ) : ?><span class="bh-muted-line">موردی وجود ندارد.</span><?php else : foreach ( $data['low_stock_items'] as $product ) : ?><a href="<?php echo esc_url( get_edit_post_link( $product['id'] ) ); ?>" class="bh-mini-row"><span class="bh-product-cell"><?php if(!empty($product['image'])): ?><img src="<?php echo esc_url($product['image']); ?>" alt="" loading="lazy"><?php endif; ?><span><?php echo esc_html( $product['name'] ); ?></span></span><strong><?php echo esc_html( $product['quantity'] ); ?></strong></a><?php endforeach; endif; ?></div><div><h3>پرفروش‌ها</h3><?php if ( empty( $data['top_products'] ) ) : ?><span class="bh-muted-line">پس از فروش نمایش داده می‌شود.</span><?php else : foreach ( array_slice( $data['top_products'], 0, 4 ) as $product ) : ?><div class="bh-mini-row"><span class="bh-product-cell"><?php if(!empty($product['image'])): ?><img src="<?php echo esc_url($product['image']); ?>" alt="" loading="lazy"><?php endif; ?><span><?php echo esc_html( $product['name'] ); ?><small><?php echo esc_html( $product['quantity'] ); ?> عدد</small></span></span><strong><?php echo wp_kses_post( $product['revenue'] ); ?></strong></div><?php endforeach; endif; ?></div></div></section></div>
